def f(g):
    g=[r[:] for r in g]; H=len(g); W=len(g[0])
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    # rectangle color: the color forming a solid block (largest connected region not bg)
    seen=[[False]*W for _ in range(H)]; best=None; bc=None
    for i in range(H):
        for j in range(W):
            if not seen[i][j] and g[i][j]!=bg:
                st=[(i,j)]; cells=[]
                while st:
                    a,b=st.pop()
                    if seen[a][b] or g[a][b]!=g[i][j]: continue
                    seen[a][b]=True; cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==g[i][j]: st.append((x,y))
                if best is None or len(cells)>len(best): best,c=b=cells, g[i][j]
    rset=set(best); rt=c
    res=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j] not in (bg,rt) and (i,j) not in rset:
                c=g[i][j]
                inrect=(min(r for r,_ in rset)<=i<=max(r for r,_ in rset) and min(c for _,c in rset)<=j<=max(c for _,c in rset))
                # direction: toward rectangle
                if min(r for r,_ in rset)>i or max(r for r,_ in rset)<i:
                    d=1 if min(r for r,_ in rset)>i else -1
                    k=i+d
                    while True:
                        if rset.__contains__((k,j)): res[k][j]=c; break
                        k+=d
                elif min(c for _,c in rset)>j or max(c for _,c in rset)<j:
                    d=1 if min(c for _,c in rset)>j else -1
                    k=j+d
                    while True:
                        if (i,k) in rset: res[i][k]=c; break
                        k+=d
    return res
